-- One row per store (only one script is ever registered per install).
-- script_id is BigCommerce's own opaque id, not generated by this app.
CREATE TABLE store_storefront_scripts (
  store_hash TEXT PRIMARY KEY REFERENCES stores (store_hash) ON DELETE CASCADE,
  script_id TEXT NOT NULL
);

-- One row per registered webhook scope, not per store — more than one
-- webhook scope may be registered over time (e.g. a future
-- store/cart/updated alongside store/order/created). hook_id is
-- BigCommerce's own opaque id.
CREATE TABLE store_webhooks (
  store_hash TEXT NOT NULL REFERENCES stores (store_hash) ON DELETE CASCADE,
  scope TEXT NOT NULL,
  hook_id TEXT NOT NULL,
  PRIMARY KEY (store_hash, scope)
);
